// AliExpress Open API - HotProduct Query
// Docs: https://openservice.aliexpress.com/doc/doc.htm?nodeId=27493&docId=137832

const appKey = $env.ALIEXPRESS_APP_KEY;
const appSecret = $env.ALIEXPRESS_APP_SECRET;
const pid = $env.ALIEXPRESS_PID;
const timestamp = new Date().toISOString().replace(/[TZ\-:]/g, '').slice(0, 14);

const params = {
  method: 'aliexpress.affiliate.hotproduct.query',
  app_key: appKey,
  timestamp,
  format: 'json',
  v: '2.0',
  sign_method: 'md5',
  target_currency: 'BRL',
  target_language: 'PT',
  ship_to_country: 'BR',
  tracking_id: pid,
  page_size: '30',
  page_no: '1'
};

// Assinatura MD5
const crypto = require('crypto');
const sortedKeys = Object.keys(params).sort();
const signStr = appSecret + sortedKeys.map(k => k + params[k]).join('') + appSecret;
params.sign = crypto.createHash('md5').update(signStr).digest('hex').toUpperCase();

return { json: { params } };

const resp = $input.item.json;
const products = resp.aliexpress_affiliate_hotproduct_query_response?.resp_result?.result?.products?.product || [];

return products.map(p => ({
  json: {
    fonte: 'aliexpress',
    item_id: p.product_id,
    titulo: p.product_title,
    preco: parseFloat(p.target_sale_price || 0),
    preco_original: parseFloat(p.target_original_price || 0),
    desconto_pct: parseInt(p.discount || 0),
    imagem: p.product_main_image_url,
    link_original: p.product_detail_url,
    link_afiliado: p.promotion_link,
    comissao_pct: parseFloat(p.commission_rate || 0),
    categoria: 'super-deal',
    coletado_em: new Date().toISOString()
  }
}));
